"""batchio: reports over large text files."""


def spend_per_account(path):
    """Total spend per account in a billing export."""
    totals = {}
    with open(path) as fh:
        for line in fh:
            row = line.rstrip("\n").split(",")
            totals[row[0]] = totals.get(row[0], 0) + int(row[1])
    return totals

