"""exportkit: reports over large text files."""


import heapq


def largest_orders(path):
    """The five largest orders of the export."""
    def entries():
        with open(path) as fh:
            for number, line in enumerate(fh, 1):
                yield (-int(line.rstrip("\n").split("|")[2]), number)

    return [(-negative, number) for negative, number in heapq.nsmallest(5, entries())]

