solution.opsreports/reader.py:
"""opsreports: reports over large text files."""


def longest_streak(path):
    """The longest stretch of requests from a single host."""
    best = (None, 0)
    current, length = None, 0
    with open(path) as fh:
        for line in fh:
            key = line.rstrip("\n").split(" ")[1]
            if key == current:
                length += 1
            else:
                current, length = key, 1
            if length > best[1]:
                best = (current, length)
    return best

